private static int getMemUnitIndexFromRequestStr(String memStr) {
    int unitIndex = -1;
    for (int i = 0; i < memStr.length(); i++) {
        if (!Character.isDigit(memStr.charAt(i)) && memStr.charAt(i) != '.') {
            unitIndex = i;
            break;
        }
    }
    return unitIndex;
}
